window.BAGMATI_GUIDE.places.forEach(p=>{const id=['kathmandu','chitwan'].includes(p.id)?p.id:'central-'+p.id;const d={id,bagmatiId:p.id,isBagmati:true,name:p.name,tag:p.label,category:p.group==='heritage'?'culture':p.group,image:'bagmati/'+p.image.replace(/\.jpg$/,''),alt:p.alt,line:p.tagline,region:p.districts.join(' · '),time:p.effortShort,season:p.seasonShort,description:p.description,highlights:[p.access,p.effort,p.care],note:p.season,source:p.sources[0]};const existing=destinations.findIndex(x=>x.id===id);if(existing>=0)destinations[existing]=d;else destinations.push(d);});
window.GANDAKI_GUIDE.places.forEach(p=>{const id=['pokhara','mustang','annapurna'].includes(p.id)?p.id:'lake-'+p.id;const d={id,gandakiId:p.id,isGandaki:true,name:p.name,tag:p.label,category:p.group==='heritage'?'culture':p.group,image:'gandaki/'+p.image.replace(/\.jpg$/,''),alt:p.alt,line:p.tagline,region:p.districts.join(' · '),time:p.effortShort,season:p.seasonShort,description:p.description,highlights:[p.access,p.effort,p.care],note:p.season,source:p.sources[0]};const existing=destinations.findIndex(x=>x.id===id);if(existing>=0)destinations[existing]=d;else destinations.push(d);});
window.LUMBINI_GUIDE.places.forEach(p=>{const id=['lumbini'].includes(p.id)?p.id:'peace-'+p.id;const d={id,lumbiniId:p.id,isLumbini:true,name:p.name,tag:p.label,category:p.group==='heritage'?'culture':p.group,image:'lumbini/'+p.image.replace(/\.jpg$/,''),alt:p.alt,line:p.tagline,region:p.districts.join(' · '),time:p.effortShort,season:p.seasonShort,description:p.description,highlights:[p.access,p.effort,p.care],note:p.season,source:p.sources[0]};const existing=destinations.findIndex(x=>x.id===id);if(existing>=0)destinations[existing]=d;else destinations.push(d);});
