const seasons = {
 spring:{title:'The mountains wake in color.',label:'TRAILS, BLOSSOMS & FRESH BEGINNINGS',image:'annapurna',alt:'Forested Himalayan landscape in the Annapurna region',copy:'Rhododendron season and a favorite time for walking. Spring is a good starting point for Himalayan plans, with conditions changing by altitude and route.',tags:['Mountain trails','Valley walks','March–May'],note:'Spring is a popular walking season. Confirm trail and transport conditions with a local operator.'},
 autumn:{title:'A little more clarity. Everywhere.',label:'CRISP AIR & OPEN HORIZONS',image:'sunrise',alt:'Himalayan peak in golden morning light',copy:'After the monsoon, October and November often bring clearer skies. It’s a popular season for mountain views, walking and journeys between the valleys.',tags:['Mountain views','Popular trekking season','September–November'],note:'Autumn is popular, particularly October and November. Reserve transport and stays ahead; keep weather buffer time.'},
 winter:{title:'Quiet days. A softer kind of wonder.',label:'LOWLAND JOURNEYS & SLOWER MOMENTS',image:'lumbini',alt:'Lumbini World Peace Pagoda',copy:'Think cultural days in the valleys and time in the southern lowlands. Higher trails can be very cold or snow-covered, so shape your route around lower elevations.',tags:['Cultural journeys','Southern lowlands','December–February'],note:'Expect cold mornings and evenings. Higher trails can be affected by snow; keep this route focused on the valleys and lowlands.'},
 monsoon:{title:'A thousand shades of green.',label:'RAIN-SOAKED VALLEYS & SLOW TRAVEL',image:'pokhara',alt:'Misty lake and hills in Pokhara',copy:'Rain transforms the hills, while clouds often hide the peaks. Choose a flexible, slower journey with indoor cultural stops and plenty of room for weather-related changes.',tags:['Lush landscapes','Flexible plans','June–August'],note:'Monsoon rains can disrupt roads, flights and outdoor activities, and may extend into September. Keep extra buffer days and check local conditions.'}
};
const creditList=[['Everest','Fernando Saltos','https://unsplash.com/photos/wik-W8UfagA'],['Rara Lake','ashok acharya','https://unsplash.com/photos/L9tIGNCyCJY'],['Ilam tea gardens','kabita Darlami','https://unsplash.com/photos/GuT5xRY97Us'],['Janaki Mandir','Diya Pokharel','https://unsplash.com/photos/iTNPhZjLWPY'],['Himalayan sunrise','Embla Voss','https://unsplash.com/photos/OSnGmbS0I-c'],['Annapurna landscape','Raimond Klavins','https://unsplash.com/photos/T3Mi-jGUdXk'],['Pokhara · Phewa Lake','Iuliia Dutchak','https://unsplash.com/photos/W3o_CUQgyUY'],['Kathmandu · Boudhanath','Raimond Klavins','https://unsplash.com/photos/KKm1ua7MSf0'],['Chitwan wildlife','Martijn Vonk','https://unsplash.com/photos/aZFjQgDK8y0'],['Mustang landscape','Francesca Varisco','https://unsplash.com/photos/jM1tlSR-XSI'],['Lumbini · World Peace Pagoda','ashok acharya','https://unsplash.com/photos/Ly9dDfCmCkk']];
let saved=[];let savedPlan=null;let storageAvailable=true;
try { const raw=JSON.parse(localStorage.getItem('nepal-saved')||'[]');saved=Array.isArray(raw)?raw.filter(x=>destinations.some(d=>d.id===x)):[]; const p=JSON.parse(localStorage.getItem('nepal-plan')||'null'); if(p && [7,10,14].includes(p.days)&&['balanced','culture','nature','slow'].includes(p.style)&&seasons[p.season]) savedPlan={days:p.days,style:p.style,season:p.season}; } catch {storageAvailable=false;}
let activeFilter='all';let showAllPlaces=false;let currentPlan=null;let storyIndex=0;let storyTimer=null;let storyPlaying=false;let toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;notify('Saved for this visit. Browser storage is unavailable.');return false;}}
function openDialog(dialog){$$('dialog[open]').forEach(d=>d.close());dialog.showModal();document.body.classList.add('modal-open');}
$$('dialog').forEach(dialog=>{ $('.close-dialog',dialog).addEventListener('click',()=>dialog.close()); dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(dialog.id==='story-dialog')stopStory();}); dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});});
function renderCards(){$('#all-place-count').textContent=destinations.length;const matched=destinations.filter(d=>activeFilter==='all'||(activeFilter==='farwest'?d.isWest:activeFilter==='koshi'?d.isKoshi:activeFilter==='madhesh'?d.isMadhesh:activeFilter==='karnali'?d.isKarnali:activeFilter==='lumbini'?d.isLumbini:activeFilter==='gandaki'?d.isGandaki:activeFilter==='bagmati'?d.isBagmati:d.category===activeFilter));const items=activeFilter==='all'&&!showAllPlaces?matched.slice(0,6):matched;$('#more-places').hidden=activeFilter!=='all';$('#more-places').innerHTML=showAllPlaces?'Show the highlights ↑':'Explore all '+destinations.length+' places ↘';$('#destination-grid').innerHTML=items.map((d,i)=>`<article class="destination-card" style="animation-delay:${i*35}ms"><div class="card-photo"><img src="assets/${d.image}.jpg" alt="${d.alt}" loading="lazy" width="700" height="900"><div class="card-overlay"></div><button class="card-open" data-detail="${d.id}" aria-label="Explore ${d.name}"><span class="card-category">${d.tag}</span></button><button class="save-place" data-save="${d.id}" aria-label="${saved.includes(d.id)?'Unsave':'Save'} ${d.name}" aria-pressed="${saved.includes(d.id)}">${icon('heart')}</button><div class="card-caption"><div><h3>${d.name}</h3><p>${d.line}</p></div><span class="card-arrow">↗</span></div></div><div class="card-bottom"><span>${icon('pin')}${d.region}</span><span>${d.time}${d.isWest||d.isKoshi||d.isMadhesh||d.isBagmati||d.isGandaki||d.isLumbini||d.isKarnali?'':' suggested'}</span></div></article>`).join('');$('#filter-note').textContent=`${items.length} of ${destinations.length} places to fall in love with`;}
function updateSavedUI(){ $('#saved-count').textContent=saved.length;$$('[data-save]').forEach(b=>{const d=destinations.find(x=>x.id===b.dataset.save);const yes=saved.includes(d.id);b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',`${yes?'Unsave':'Save'} ${d.name}`);if(!b.classList.contains('save-place')) b.innerHTML=icon('heart')+(yes?'Saved to your places':'Save this place');});}
function toggleSave(id){const d=destinations.find(x=>x.id===id);if(!d)return;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const kept=persist('nepal-saved',saved);if(d.isWest){try{const west=JSON.parse(localStorage.getItem('nepal-farwest-journey')||'{}');west.saved=saved.filter(x=>x.startsWith('west-')).map(x=>x.slice(5));localStorage.setItem('nepal-farwest-journey',JSON.stringify(west));}catch{}}if(d.isKoshi){try{const east=JSON.parse(localStorage.getItem('nepal-koshi-journey')||'{}');east.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isKoshi).map(p=>p.koshiId);localStorage.setItem('nepal-koshi-journey',JSON.stringify(east));}catch{}}if(d.isMadhesh){try{const south=JSON.parse(localStorage.getItem('nepal-madhesh-journey')||'{}');south.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isMadhesh).map(p=>p.madheshId);localStorage.setItem('nepal-madhesh-journey',JSON.stringify(south));}catch{}}if(d.isKarnali){try{const river=JSON.parse(localStorage.getItem('nepal-karnali-journey')||'{}');river.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isKarnali).map(p=>p.karnaliId);localStorage.setItem('nepal-karnali-journey',JSON.stringify(river));}catch{}}if(d.isLumbini){try{const peace=JSON.parse(localStorage.getItem('nepal-lumbini-journey')||'{}');peace.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isLumbini).map(p=>p.lumbiniId);localStorage.setItem('nepal-lumbini-journey',JSON.stringify(peace));}catch{}}if(d.isGandaki){try{const lake=JSON.parse(localStorage.getItem('nepal-gandaki-journey')||'{}');lake.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isGandaki).map(p=>p.gandakiId);localStorage.setItem('nepal-gandaki-journey',JSON.stringify(lake));}catch{}}if(d.isBagmati){try{const central=JSON.parse(localStorage.getItem('nepal-bagmati-journey')||'{}');central.saved=saved.map(id=>destinations.find(p=>p.id===id)).filter(p=>p?.isBagmati).map(p=>p.bagmatiId);localStorage.setItem('nepal-bagmati-journey',JSON.stringify(central));}catch{}}updateSavedUI();if(kept)notify(saved.includes(id)?`${d.name} added to your dream places.`:`${d.name} removed from saved places.`);if($('#saved-dialog').open)renderSaved();}
$$('.filter').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;$$('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});renderCards();}));
function showDestination(id){if(id==='karnali-guide'){location.href='karnali.html';return;}if(id==='lumbini-guide'){location.href='lumbini.html';return;}if(id==='gandaki-guide'){location.href='gandaki.html';return;}if(id==='bagmati-guide'){location.href='bagmati.html';return;}if(id==='madhesh-guide'){location.href='madhesh.html';return;}if(id==='koshi-guide'){location.href='koshi.html';return;}if(id==='farwest-guide'){location.href='sudurpaschim.html';return;}const d=destinations.find(x=>x.id===id);if(!d)return;if(d.isWest){location.href='sudurpaschim.html#place='+d.westId;return;}if(d.isKoshi){location.href='koshi.html#place='+d.koshiId;return;}if(d.isMadhesh){location.href='madhesh.html#place='+d.madheshId;return;}if(d.isKarnali){location.href='karnali.html#place='+d.karnaliId;return;}if(d.isLumbini){location.href='lumbini.html#place='+d.lumbiniId;return;}if(d.isGandaki){location.href='gandaki.html#place='+d.gandakiId;return;}if(d.isBagmati){location.href='bagmati.html#place='+d.bagmatiId;return;}$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${d.image}.jpg" alt="${d.alt}"><div class="detail-copy"><div class="eyebrow">${d.tag} / ${d.region.toUpperCase()}</div><h2>${d.name}. <em>${d.line}</em></h2><p>${d.description}</p><div class="detail-facts"><span><small>SUGGESTED TIME</small>${d.time}</span><span><small>WHEN TO THINK ABOUT IT</small>${d.season}</span></div><h3>Make time for these.</h3><ul>${d.highlights.map(h=>`<li>${h}</li>`).join('')}</ul><p>${d.note}</p><div class="detail-actions"><button class="button saffron" data-plan>Start planning ${icon('arrow')}</button><button class="button outline" data-save="${d.id}" aria-pressed="${saved.includes(d.id)}">${icon('heart')}${saved.includes(d.id)?'Saved to your places':'Save this place'}</button></div><a class="detail-source" href="${d.source}" target="_blank" rel="noopener">Explore official destination guidance ↗</a></div>`;openDialog($('#detail-dialog'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-save],[data-detail],[data-plan],[data-remove]');if(!b)return;if(b.dataset.save)toggleSave(b.dataset.save);else if(b.dataset.detail)showDestination(b.dataset.detail);else if(b.dataset.remove)toggleSave(b.dataset.remove);else if(b.hasAttribute('data-plan')){closeMobileNav();openDialog($('#planner-dialog'));}});
function renderSaved(){const items=destinations.filter(d=>saved.includes(d.id));$('#saved-list').innerHTML=items.length?items.map(d=>`<div class="saved-item"><img src="assets/${d.image}.jpg" alt="${d.alt}"><button class="saved-info" data-detail="${d.id}"><h3>${d.name}</h3><p>${d.line}</p></button><button class="remove-saved" data-remove="${d.id}" aria-label="Remove ${d.name} from saved places">Remove</button></div>`).join(''):`<div class="empty-state">Your journey starts with a place that calls to you.<br>Tap a heart on any destination to save it here.</div>`;$('#saved-plan').innerHTML=savedPlan?`<h3>Your saved itinerary</h3><p>${savedPlan.days} days · ${styleNames[savedPlan.style]} · ${savedPlan.season}</p><button class="text-link" id="reopen-plan">Open your plan ${icon('arrow')}</button>`:'<button class="button saffron" data-plan>Dream up a journey '+icon('arrow')+'</button>';$('#reopen-plan')?.addEventListener('click',()=>{$('#plan-days').value=savedPlan.days;$('#plan-style').value=savedPlan.style;$('#plan-season').value=savedPlan.season;renderPlan(savedPlan);openDialog($('#planner-dialog'));});}
$$('[data-open-saved]').forEach(b=>b.addEventListener('click',()=>{renderSaved();openDialog($('#saved-dialog'));}));
function setSeason(name){const s=seasons[name];$$('.season-tab').forEach(b=>{const active=b.dataset.season===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;});$('#season-panel').setAttribute('aria-labelledby','tab-'+name);$('#season-panel').innerHTML=`<div class="season-content"><div class="eyebrow">${icon('sun')}${s.label}</div><h3>${s.title}</h3><p>${s.copy}</p><div class="season-tags">${s.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><img src="assets/${s.image}.jpg" alt="${s.alt}" loading="lazy">`;}
$$('.season-tab').forEach((b,i)=>{b.addEventListener('click',()=>setSeason(b.dataset.season));b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('.season-tab');const next=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:-1)+4)%4;setSeason(tabs[next].dataset.season);tabs[next].focus();});});
const styleNames={balanced:'A little of everything',culture:'Culture & connection',nature:'Nature & wildlife',slow:'Slow days & beautiful views'};
const stops={
 kathmandu:['Kathmandu Valley','Arrive, settle in and explore Boudhanath, Patan and the valley’s historic courtyards.'],
 pokhara:['Pokhara','Travel to Pokhara, unwind by Phewa Lake and leave a clear morning for a hillside viewpoint.'],
 chitwan:['Chitwan','Transfer to the lowlands. Arrange a responsible guided safari and a locally led cultural visit.'],
 lumbini:['Lumbini','Travel to Lumbini. Set aside quiet time for the sacred garden and monastic zone.'],
 bandipur:['Bandipur','Break the journey in a hill town, with slow walks and time around the old bazaar.'],
 foothills:['Annapurna foothills','Arrange a locally guided, lower-elevation village walk from the Pokhara area, matched to your comfort and conditions.'],
 valley:['Bhaktapur & the valley','Explore Bhaktapur and nearby valley communities at an easy pace, returning to Kathmandu.'],
 return:['Kathmandu & departure buffer','Return to Kathmandu before your onward flight. Keep this time flexible for transport delays and a final unhurried day.']
};
function createRoute(days,style){
 const templates={7:{balanced:[['kathmandu',2],['pokhara',3],['return',2]],culture:[['kathmandu',3],['valley',2],['return',2]],nature:[['kathmandu',2],['chitwan',3],['return',2]],slow:[['kathmandu',2],['pokhara',3],['return',2]]},10:{balanced:[['kathmandu',2],['pokhara',3],['chitwan',3],['return',2]],culture:[['kathmandu',3],['lumbini',3],['valley',2],['return',2]],nature:[['kathmandu',2],['pokhara',3],['chitwan',3],['return',2]],slow:[['kathmandu',2],['bandipur',2],['pokhara',4],['return',2]]},14:{balanced:[['kathmandu',3],['pokhara',4],['lumbini',2],['chitwan',3],['return',2]],culture:[['kathmandu',3],['bandipur',2],['pokhara',3],['lumbini',3],['valley',1],['return',2]],nature:[['kathmandu',2],['pokhara',3],['foothills',3],['chitwan',4],['return',2]],slow:[['kathmandu',3],['bandipur',2],['pokhara',5],['valley',2],['return',2]]}};
 let day=1;return templates[days][style].map(([id,n])=>{const start=day;day+=n;return {id,start,end:day-1,name:stops[id][0],description:stops[id][1]};});
}
function renderPlan(config){currentPlan={days:+config.days,style:config.style,season:config.season};const route=createRoute(currentPlan.days,currentPlan.style);const result=$('#plan-result');result.hidden=false;result.innerHTML=`<div class="eyebrow">YOUR SUGGESTED JOURNEY</div><h3>${currentPlan.days} days of <em>something different.</em></h3><p class="muted">${styleNames[currentPlan.style]} · ${currentPlan.season[0].toUpperCase()+currentPlan.season.slice(1)} · Transfers included in each stop’s day allowance</p><ol class="route-list">${route.map(r=>`<li><span>DAY ${r.start}${r.end!==r.start?' — '+r.end:''}</span><div><h4>${r.name}</h4><p>${r.description}</p></div></li>`).join('')}</ol><p class="plan-advice">${seasons[currentPlan.season].note} This is a flexible touring outline, not a high-altitude trekking schedule. Travel time varies; confirm the route, accommodation and activities with a local operator.</p><div class="plan-actions"><button class="button saffron" id="save-plan">Save my itinerary ${icon('heart')}</button><button class="button outline" id="download-plan">Download itinerary ↓</button></div><p class="planner-note">Your plan stays in this browser. Download a copy to take it with you.</p>`;$('#save-plan').addEventListener('click',()=>{savedPlan={...currentPlan};if(persist('nepal-plan',savedPlan))notify('Your itinerary is saved. Find it in your saved places.');});$('#download-plan').addEventListener('click',downloadPlan);}
$('#planner-form').addEventListener('submit',e=>{e.preventDefault();renderPlan({days:$('#plan-days').value,style:$('#plan-style').value,season:$('#plan-season').value});$('#plan-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
function downloadPlan(){if(!currentPlan)return;const p=currentPlan;const route=createRoute(p.days,p.style);const content=`NEPAL — BEYOND THE ORDINARY\nYour ${p.days}-day journey\n${styleNames[p.style]} | ${p.season}\n\nSuggested touring itinerary. Transfers are included within each stop's day allowance.\n\n${route.map(r=>`DAY ${r.start}${r.end!==r.start?'–'+r.end:''} | ${r.name}\n${r.description}`).join('\n\n')}\n\nSEASONAL NOTES\n${seasons[p.season].note}\n\nBEFORE YOU GO\nThis is travel inspiration, not a booking or high-altitude trekking schedule. Confirm entry requirements, permits, transport, route conditions, accommodation and activities with relevant authorities and a local operator. Allow additional buffer time where needed.\n\nOfficial planning guidance: https://ntb.gov.np/plan-your-trip\n\nSaved places: ${destinations.filter(d=>saved.includes(d.id)).map(d=>d.name).join(', ')||'None yet'}\n\nCreated with Nepal — Beyond the Ordinary\nhttps://nepal-beyond-ordinary.brinybull4.chatgpt.site\n`;const blob=new Blob([content],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`My-Nepal-${p.days}-Day-Journey.txt`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Your Nepal itinerary is ready to download.');}
const experiences={trails:{title:'A path worth taking.',image:'annapurna',alt:'Annapurna foothills and forests',body:'You don’t have to chase a summit to find a mountain moment. Start with a village walk around the Annapurna foothills, or plan a longer route with a qualified local guide.',items:['Choose a route that fits your walking experience.','Leave time for villages, viewpoints and teahouse stops.','For high-altitude travel, plan acclimatization and weather buffers separately.'],destination:'annapurna'},culture:{title:'Tradition, still alive.',image:'kathmandu',alt:'Boudhanath Stupa in Kathmandu',body:'Follow a courtyard into another century, then step back into the energy of everyday life. Kathmandu Valley’s architecture and sacred places are part of living communities.',items:['Spend a morning walking through Patan or Bhaktapur.','Let a local guide bring the details into focus.','Ask before taking portraits, and follow guidance at sacred sites.'],destination:'kathmandu'},nature:{title:'Let the wild lead.',image:'chitwan',alt:'Chitwan one-horned rhinoceros',body:'Some of Nepal’s most memorable moments happen close to the ground. Around Chitwan, take your cues from the river, the forest and the people who know them.',items:['Go with a licensed local naturalist or park guide.','Enjoy birdwatching and responsible jeep safaris.','Give wildlife space, and remember that sightings are never guaranteed.'],destination:'chitwan'},food:{title:'Pull up a chair.',image:'kathmandu',alt:'Kathmandu’s Boudhanath neighborhood',body:'A plate of momos. A comforting dal bhat. A cup of chiya that turns into a conversation. Make room for Nepal’s food traditions, one locally run kitchen at a time.',items:['Try a locally run cooking class in Kathmandu or Pokhara.','Explore Newari food with a knowledgeable local host.','Tell your host about any allergies or dietary requirements.'],destination:'kathmandu'}};
$$('[data-experience]').forEach(b=>b.addEventListener('click',()=>{const e=experiences[b.dataset.experience];$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${e.image}.jpg" alt="${e.alt}"><div class="detail-copy"><div class="eyebrow">GO A LITTLE DEEPER</div><h2>${e.title}</h2><p>${e.body}</p><h3>A few ways to begin.</h3><ul>${e.items.map(t=>`<li>${t}</li>`).join('')}</ul><div class="detail-actions"><button class="button saffron" data-plan>Make it part of your journey ${icon('arrow')}</button><button class="button outline" data-detail="${e.destination}">Explore the place ↗</button></div></div>`;openDialog($('#detail-dialog'));}));
const heroScenes=[{image:'sunrise',alt:'Sunrise on a snow-covered Himalayan peak in Nepal',location:'THE HIMALAYAS, NEPAL'},{image:'pokhara',alt:'Boats on Phewa Lake in Pokhara',location:'PHEWA LAKE, POKHARA'},{image:'kathmandu',alt:'Boudhanath Stupa in Kathmandu',location:'BOUDHANATH, KATHMANDU'}];
$$('[data-scene]').forEach(b=>b.addEventListener('click',()=>{const s=heroScenes[+b.dataset.scene];$('#hero-image').src=`assets/${s.image}.jpg`;$('#hero-image').alt=s.alt;$('#hero-location').textContent=s.location;$$('[data-scene]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});}));
const storySlides=destinations.map(d=>({image:d.image,alt:d.alt,title:d.line,caption:d.description.split('. ')[0]+'.',label:d.name.toUpperCase()+' / NEPAL'}));
function renderStory(){const s=storySlides[storyIndex];$('#story-image').src=`assets/${s.image}.jpg`;$('#story-image').alt=s.alt;$('#story-kicker').textContent=s.label;$('#story-title').textContent=s.title;$('#story-caption').textContent=s.caption;$('#story-count').textContent=`${String(storyIndex+1).padStart(2,'0')} / ${String(storySlides.length).padStart(2,'0')}`;}
function stopStory(){clearInterval(storyTimer);storyTimer=null;storyPlaying=false;$('#story-pause').textContent='▶';$('#story-pause').setAttribute('aria-label','Play photo story');}
function playStory(){stopStory();storyPlaying=true;$('#story-pause').textContent='Ⅱ';$('#story-pause').setAttribute('aria-label','Pause photo story');storyTimer=setInterval(()=>{storyIndex=(storyIndex+1)%storySlides.length;renderStory();},6000);}
function storyNext(delta){storyIndex=(storyIndex+delta+storySlides.length)%storySlides.length;renderStory();if(storyPlaying)playStory();}
$('#watch-story').addEventListener('click',()=>{storyIndex=0;renderStory();openDialog($('#story-dialog'));if(!matchMedia('(prefers-reduced-motion: reduce)').matches)playStory();else stopStory();});$('#story-prev').addEventListener('click',()=>storyNext(-1));$('#story-next').addEventListener('click',()=>storyNext(1));$('#story-pause').addEventListener('click',()=>storyPlaying?stopStory():playStory());$('#story-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();storyNext(1)}if(e.key==='ArrowLeft'){e.preventDefault();storyNext(-1)}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStory();});
$('#credits-button').addEventListener('click',()=>{$('#photo-credits').innerHTML=creditList.map(([name,author,url])=>`<div class="credit-item"><span>${name}</span><a href="${url}" target="_blank" rel="noopener">${author} / Unsplash ↗</a></div>`).join('');openDialog($('#credits-dialog'));});
function closeMobileNav(){$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',open);$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});$$('#mobile-nav a').forEach(a=>a.addEventListener('click',closeMobileNav));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileNav();});
let ticking=false;addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{$('#header').classList.toggle('sticky',scrollY>200);ticking=false;});ticking=true;}},{passive:true});
$('#more-places').addEventListener('click',()=>{showAllPlaces=!showAllPlaces;renderCards();if(!showAllPlaces)$('#destinations').scrollIntoView({behavior:'smooth'});});
renderCards();updateSavedUI();setSeason('spring');
